function parseAlive(alive,side){const m=String(alive||'5V5').match(/(\d)\s*V\s*(\d)/i);let a=m?+m[1]:5,b=m?+m[2]:5;return String(side||'').startsWith('CT')?{ct:a,t:b}:{t:a,ct:b}}
function cappedMarkers(points,count,prefix){const n=Math.max(1,Math.min(count,points.length));return points.slice(0,n).map((p,i)=>[p[0],p[1],prefix+(i+1)])}
function pathD(points){return points.map((p,i)=>(i?'L':'M')+p[0]+' '+p[1]).join(' ')}
function overlayBadge(x,y,text,variant='main',color='#eef3f7'){
 const fs=variant==='thumb'?10:12,w=Math.max(68,text.length*(variant==='thumb'?7:8)+18),h=variant==='thumb'?23:27;
 return `<g><rect x="${x-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="${h/2}" fill="rgba(5,9,13,.74)" stroke="rgba(255,255,255,.12)"/><text x="${x}" y="${y+fs*.34}" text-anchor="middle" fill="${color}" font-family="Arial,sans-serif" font-size="${fs}" font-weight="800">${esc(text)}</text></g>`
}
function overlayMarker(x,y,label,color,variant='main'){const r=variant==='thumb'?13:17,ring=variant==='thumb'?22:28;return `<g><circle cx="${x}" cy="${y}" r="${ring}" fill="${color}" opacity=".14"/><circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/><circle cx="${x}" cy="${y}" r="${r+6}" fill="none" stroke="${color}" stroke-width="2" opacity=".45"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="#071018" font-family="monospace" font-size="${variant==='thumb'?9:10}" font-weight="900">${label}</text></g>`}
function tacticalOverlay(scene,variant='main'){
 const info=MAP_LAYOUTS[scene.mapInfo.map]||MAP_LAYOUTS['MIRAGE'],accent=scene.mapInfo.accent||'#ffad19',ct='#5cbcff';
 const counts=parseAlive(scene.alive,scene.side),t=cappedMarkers(info.tSpots,Math.min(counts.t,4),'T'),c=cappedMarkers(info.ctSpots,Math.min(counts.ct,3),'CT');
 const dim=variant==='thumb'?'thumb':'main';
 const routes=(info.routes||[]).map((pts,i)=>`<g><path d="${pathD(pts)}" fill="none" stroke="${i===0?accent:ct}" stroke-width="${variant==='thumb'?5:7}" stroke-linecap="round" stroke-dasharray="10 12" opacity=".95"/><path d="${pathD(pts)}" fill="none" stroke="${i===0?accent:ct}" stroke-width="${variant==='thumb'?14:18}" stroke-linecap="round" opacity=".10"/></g>`).join('');
 const markers=t.map(([x,y,l])=>overlayMarker(x,y,l,accent,dim)).join('')+c.map(([x,y,l])=>overlayMarker(x,y,l,ct,dim)).join('');
 const utils=(info.smokes||[]).map(([x,y,label])=>`<g><circle cx="${x}" cy="${y}" r="${variant==='thumb'?20:25}" fill="#d7e0e7" opacity=".18"/><circle cx="${x+13}" cy="${y+7}" r="${variant==='thumb'?13:16}" fill="#d7e0e7" opacity=".11"/>${overlayBadge(x,y-26,label,dim,'#dbe4ea')}</g>`).join('');
 const flash=info.flash?`<g><circle cx="${info.flash[0]}" cy="${info.flash[1]}" r="${variant==='thumb'?16:20}" fill="rgba(255,255,255,.10)" stroke="rgba(255,255,255,.44)"/><text x="${info.flash[0]}" y="${info.flash[1]+4}" text-anchor="middle" fill="#fff" font-family="monospace" font-size="${variant==='thumb'?8:10}" font-weight="900">F</text></g>`:'';
 const bomb=(scene.goal.includes('POST')||scene.goal.includes('AFTER')||scene.goal.includes('CLUTCH'))&&info.bomb&&info.bomb[0]?`<g><rect x="${info.bomb[0]-35}" y="${info.bomb[1]-17}" width="70" height="34" rx="10" fill="rgba(255,173,25,.20)" stroke="rgba(255,173,25,.58)"/><text x="${info.bomb[0]}" y="${info.bomb[1]+5}" text-anchor="middle" fill="#ffd17a" font-family="monospace" font-size="${variant==='thumb'?11:13}" font-weight="900">BOMB</text></g>`:'';
 const title=variant==='thumb'?`<g><rect x="26" y="24" width="270" height="78" rx="16" fill="rgba(5,9,13,.68)" stroke="rgba(255,255,255,.10)"/><text x="46" y="50" fill="${accent}" font-family="monospace" font-size="12" font-weight="900">${esc(info.key)} // ${esc(info.site)}</text><text x="46" y="80" fill="#eef3f7" font-family="Arial,sans-serif" font-size="25" font-weight="900">${esc(scene.state)}</text></g>`:'';
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="700" viewBox="0 0 1000 700"><rect width="1000" height="700" fill="transparent"/><g opacity="${variant==='hero'?.72:1}">${routes}${utils}${flash}${bomb}${markers}${title}</g></svg>`;
 return svgUri(svg)
}
function mapScene(scene,variant='main'){return tacticalOverlay(scene,variant)}
function mapThumb(scene,label){const s=Object.assign({},scene,{state:label||scene.state});return tacticalOverlay(s,'thumb')}
function buildScenario(i){
 const mapInfo=MAP_LIBRARY[i%MAP_LIBRARY.length],situation=SITUATION_LIBRARY[i%SITUATION_LIBRARY.length],question=QUESTION_FLAVORS[i%QUESTION_FLAVORS.length];
 const skins=[SKIN_LIBRARY[i%SKIN_LIBRARY.length],SKIN_LIBRARY[(i+1)%SKIN_LIBRARY.length],SKIN_LIBRARY[(i+2)%SKIN_LIBRARY.length]];
 const layout=MAP_LAYOUTS[mapInfo.map]||MAP_LAYOUTS['MIRAGE'];
 return {index:i+1,mapInfo,...situation,question,skins,photo:realMapPhoto(mapInfo.map,false),photoAlt:realMapPhoto(mapInfo.map,true),thumbA:layout.thumbs[0],thumbB:layout.thumbs[1],thumbC:(layout.thumbs&&layout.thumbs[2])||layout.hint,intelTitle:`${mapInfo.map} · ${mapInfo.site} · ${situation.goal}`,intel:[`<strong>地图场景：</strong>${mapInfo.map} ${mapInfo.site}，${situation.alive}，${situation.side}，${situation.econ}。`,`<strong>已知信息：</strong>${situation.known}`,`<strong>判断重点：</strong>${situation.focus}`,`<strong>关键区域：</strong>${layout.hint}`]}
}
const TACTICAL_PACKS=QUESTIONS.map((_,i)=>buildScenario(i));




let idx=0,answers=[],lastResult=null,deferredInstallPrompt=null;
const $=id=>document.getElementById(id);
const safeStore=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
