 $('playerName').textContent=p.name;$('playerReal').textContent=p.real;$('playerRole').textContent=p.role;$('playerTag').textContent=p.tag;$('playerDesc').textContent=p.desc;$('playerStrength').textContent=p.strength;$('playerRisk').textContent=p.risk;$('resultScore').textContent=Math.round(raw.score)+'%';$('resultRole').textContent=meta.role;$('resultImpact').textContent=meta.impact;$('resultTempo').textContent=meta.tempo;
 loadPeakImage($('playerPeakPoster'),p);
